package com.dukaops.backend.contact; import java.util.*; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; public interface SupplierRepository extends JpaRepository<Supplier,UUID>{Optional<Supplier> findByTenant_IdAndId(UUID t,UUID id); @Query("select s from Supplier s where s.tenant.id=:t and (lower(s.businessName) like lower(concat('%',:q,'%')) or lower(s.email) like lower(concat('%',:q,'%'))) order by s.businessName") Page<Supplier> search(@Param("t")UUID t,@Param("q")String q,Pageable p); Page<Supplier> findByTenant_Id(UUID t,Pageable p); Page<Supplier> findByTenant_IdAndStatus(UUID t,ContactStatus s,Pageable p); boolean existsByTenant_IdAndEmailIgnoreCase(UUID t,String e); boolean existsByTenant_IdAndEmailIgnoreCaseAndIdNot(UUID t,String e,UUID id);}
